CREATE DATABASE IF NOT EXISTS ububiko_smart CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ububiko_smart;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN','STOCK_MANAGER','CASHIER','STOREKEEPER') NOT NULL DEFAULT 'CASHIER',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,sku VARCHAR(80) NOT NULL UNIQUE,category_id BIGINT UNSIGNED NULL,unit VARCHAR(30) NOT NULL DEFAULT 'pcs',purchase_price DECIMAL(14,2) NOT NULL DEFAULT 0,selling_price DECIMAL(14,2) NOT NULL DEFAULT 0,min_quantity DECIMAL(14,3) NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE stock_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,movement_type ENUM('IN','OUT','ADJUSTMENT') NOT NULL,quantity DECIMAL(14,3) NOT NULL,reason VARCHAR(500),requested_by BIGINT UNSIGNED NOT NULL,status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',reviewed_by BIGINT UNSIGNED NULL,review_comment VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(requested_by) REFERENCES users(id),FOREIGN KEY(reviewed_by) REFERENCES users(id));
CREATE TABLE stock_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,movement_type ENUM('IN','OUT','ADJUSTMENT') NOT NULL,quantity DECIMAL(14,3) NOT NULL,reference VARCHAR(100),created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(approved_by) REFERENCES users(id));
CREATE TABLE suppliers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,phone VARCHAR(40),email VARCHAR(190),address VARCHAR(255));
CREATE TABLE customers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,phone VARCHAR(40),email VARCHAR(190));
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,entity VARCHAR(80),entity_id BIGINT UNSIGNED,details JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
INSERT IGNORE INTO categories(name) VALUES('Ibiribwa'),('Ibikoresho'),('Ibinyobwa'),('Ibindi');
